import json

import boto3


def parse_json_secret(payload, config=None):
    config = config or {}
    client = boto3.client("secretsmanager", region_name=config.get("region"))
    response = client.get_secret_value(SecretId=payload["secret_id"])
    secret_string = response["SecretString"]
    parsed_secret = json.loads(secret_string)
    return {"parsed_secret": parsed_secret}

import boto3


def rotate_secret_version(payload, config=None):
    config = config or {}
    client = boto3.client("secretsmanager", region_name=config.get("region"))

    secret_id = payload["secret_id"]
    version_id = payload.get("version_id")
    version_stage = payload.get("version_stage", "AWSCURRENT")

    if version_id:
        response = client.get_secret_value(SecretId=secret_id, VersionId=version_id)
    else:
        response = client.get_secret_value(SecretId=secret_id, VersionStage=[version_stage])

    value = response["SecretString"] if "SecretString" in response else response["SecretBinary"].decode("utf-8")
    return {"secret_value": value, "version_id": response.get("VersionId"), "version_stages": response.get("VersionStages")}

import boto3

def get_secrets_manager_client(region_name=None):
    return boto3.client("secretsmanager", region_name=region_name)

from dataclasses import dataclass
from typing import Optional, Dict, Any

@dataclass
class SecretPayload:
    secret_id: str
    key_field: Optional[str] = None
    version_id: Optional[str] = None
    version_stage: Optional[str] = None

@dataclass
class DBSecret:
    username: str
    password: str
    host: str
    port: int
    dbname: str

@dataclass
class ParsedSecret:
    parsed_secret: Dict[str, Any]

from google.cloud import aiplatform

def check_secret_label_safety(text: str, project_id: str, location: str) -> dict:
    aiplatform.init(project=project_id, location=location)
    model = aiplatform.preview.generative_models.GenerativeModel("gemini-pro")
    response = model.generate_content([f"Analyze the following text for safety concerns: {text}"])

    safety_attributes = {
        "harm_category": {
            category.name: category.probability.name
            for category in response.candidates[0].safety_ratings
        },
        "blocked": response.candidates[0].safety_ratings[0].blocked # If any harm category is BLOCK_LIKELY or higher
    }
    return safety_attributes
